-- 27 developers, exactly as the site lists them today.
insert into cms.developers (slug, name_en, name_ar, tagline_en, tagline_ar,
  description_en, description_ar, areas_line_en, areas_line_ar, founded_year,
  brand_colour, status)
select v.*, 'published' from (values
  ('sodic','SODIC','سوديك','Design-led living, East & West Cairo','حياة بتصميم مميّز شرق وغرب القاهرة','Listed on the EGX since 1996 and 85% owned by the ALDAR–ADQ consortium since 2021. Twenty-eight years of operations in West Cairo, East Cairo and the North Coast, with over 14,000 units delivered — 91% of them ahead of schedule — and communities that are home to more than 30,000 people.','مقيّدة في البورصة المصرية منذ ١٩٩٦، ويملك تحالف «الدار وADQ» ٨٥٪ منها منذ ٢٠٢١. ثمانية وعشرون عاماً من العمل في غرب القاهرة وشرقها وعلى الساحل الشمالي، بأكثر من ١٤٬٠٠٠ وحدة مسلَّمة — ٩١٪ منها قبل موعدها — ومجتمعات يسكنها أكثر من ٣٠٬٠٠٠ نسمة.','New Cairo · Sheikh Zayed · Ras El Hekma','القاهرة الجديدة · الشيخ زايد · رأس الحكمة',1996,'#0d6e7d'),
  ('palmhills','Palm Hills Developments','بالم هيلز','Large-scale communities & coast','مجتمعات كبرى ووجهات ساحلية','One of Egypt’s largest developers, building integrated residential communities and North Coast destinations.','من أكبر المطوّرين في مصر، يبني مجتمعات سكنية متكاملة ووجهات على الساحل الشمالي.','New Cairo · Sheikh Zayed · North Coast','القاهرة الجديدة · الشيخ زايد · الساحل الشمالي',2005,'#1e7a5a'),
  ('mountainview','Mountain View','ماونتن ڤيو','Experience Happiness','عيش السعادة','Launched in 2005 to develop integrated communities around a science of happiness. Twenty years on it has delivered 23 projects and 17,000 units to 50,000 families, and holds a land bank of more than 6,000 acres across East Cairo, West Cairo and the coast.','تأسّست عام ٢٠٠٥ لتطوير مجتمعات عمرانية متكاملة قائمة على علم السعادة. وبعد عشرين عاماً سلّمت ٢٣ مشروعاً و١٧ ألف وحدة لخمسين ألف أسرة، وتملك محفظة أراضٍ تتجاوز ٦٠٠٠ فدان في شرق القاهرة وغربها وعلى الساحل.','New Cairo · 6th of October · North Coast','القاهرة الجديدة · ٦ أكتوبر · الساحل الشمالي',2005,'#2b6ca8'),
  ('ora','ORA Developers','أورا','Premium, design-led destinations','وجهات راقية بتصميم مميّز','A premium developer creating high-design lifestyle destinations with strong architecture and amenities.','مطوّر راقٍ يبتكر وجهات لايف ستايل عالية التصميم بعمارة ومرافق قوية.','New Cairo · Sheikh Zayed · North Coast','القاهرة الجديدة · الشيخ زايد · الساحل الشمالي',2016,'#6d52a3'),
  ('tatweer','Tatweer Misr','تطوير مصر','Value communities & coastal resorts','مجتمعات اقتصادية ومنتجعات ساحلية','A developer focused on integrated communities and coastal resorts with a value orientation.','مطوّر يركّز على المجتمعات المتكاملة والمنتجعات الساحلية بتوجّه اقتصادي.','Ain Sokhna · Mostakbal City · Ras El Hekma · North Coast · Sheikh Zayed','العين السخنة · مدينة المستقبل · رأس الحكمة · الساحل الشمالي · الشيخ زايد',2014,'#b0692c'),
  ('misritalia','Misr Italia Properties','مصر إيطاليا','Biophilic, tech-enabled communities','مجتمعات خضراء بتقنيات حديثة','A developer associated with green, technology-enabled communities, active in the New Capital and on the coast.','مطوّر مرتبط بمجتمعات خضراء مزوّدة بالتقنيات، نشط في العاصمة الإدارية والساحل.','New Administrative Capital · North Coast','العاصمة الإدارية · الساحل الشمالي',1996,'#2f8f6a'),
  ('marakez','Marakez','مراكز','Egypt’s leading mixed-use developer','المطوّر الرائد متعدد الاستخدامات في مصر','The leading mixed-use developer in Egypt, and the only one that builds the mall, the offices and the entertainment its homes sit around. Grown from a single asset — Mall of Arabia — into Aeon, District Five, Crescent Walk and ramla, and backed by Fawaz Al Hokair Group and its own contractor, FAS Construction.','المطوّر الرائد متعدد الاستخدامات في مصر، والوحيد الذي يبني المول والمكاتب والترفيه التي تلتف حولها مساكنه. نمت من أصل واحد — مول العرب — إلى إيون وديستريكت فايف وكريسنت ووك ورملة، بدعم من مجموعة فواز الحكير ومقاولها الخاص «FAS Construction».','New Cairo · 6th of October · Ras El Hekma · Red Sea','القاهرة الجديدة · ٦ أكتوبر · رأس الحكمة · البحر الأحمر',2014,'#b0473f'),
  ('lmd','LMD','إل إم دي','Design-forward communities','مجتمعات بتصميم متقدّم','A developer known for design-forward, art-infused communities and walkable urban districts.','مطوّر معروف بمجتمعات بتصميم متقدّم وطابع فني وأحياء حضرية.','New Cairo · North Coast','القاهرة الجديدة · الساحل الشمالي',2013,'#3a5a8c'),
  ('hydepark','Hyde Park Developments','هايد بارك','Central-park living in East Cairo','حياة حول حديقة مركزية بشرق القاهرة','A developer building large park-centred communities in East Cairo and coastal projects.','مطوّر يبني مجتمعات كبيرة حول حدائق مركزية بشرق القاهرة ومشروعات ساحلية.','New Cairo · North Coast','القاهرة الجديدة · الساحل الشمالي',2011,'#3f7d3a'),
  ('marasem','Al Marasem Development','المراسم','Prime Fifth Settlement communities','مجتمعات مميّزة بالتجمع الخامس','A developer with a prime footprint in the Fifth Settlement and a background in construction and hospitality.','مطوّر بحضور مميّز في التجمع الخامس وخلفية في الإنشاءات والضيافة.','Fifth Settlement · New Cairo','التجمع الخامس · القاهرة الجديدة',2002,'#8a6d33'),
  ('qataridiar','Qatari Diar','الديار القطرية','Large mixed-use destinations','وجهات كبرى متعددة الاستخدامات','A major regional developer associated with large mixed-use destinations, active in Egypt through flagship projects.','مطوّر إقليمي كبير مرتبط بوجهات ضخمة متعددة الاستخدامات، ونشط في مصر عبر مشروعات كبرى.','New Administrative Capital · North Coast','العاصمة الإدارية · الساحل الشمالي',2005,'#26305f'),
  ('orascom','Orascom Development','أوراسكوم للتطوير','Integrated towns & resorts','مدن ومنتجعات متكاملة','A developer known for fully integrated towns and resort destinations across Egypt and the coast.','مطوّر معروف بالمدن المتكاملة والوجهات السياحية في مصر والساحل.','6th of October · North Coast · Red Sea','٦ أكتوبر · الساحل الشمالي · البحر الأحمر',1994,'#a9812f'),
  ('msquared','M squared','إم سكويرد','Masterfully minded spaces','مساحات مصمَّمة بإتقان','Founded in 2012, M squared is the real estate arm of INTRO Investments Holding — an Egyptian conglomerate established in the 1970s and privately owned by the Abbas family. It builds across Ras Al Hekma, New Cairo, Maadi and 6th of October, and runs its own hospitality arm.','تأسّست عام ٢٠١٢، وإم سكويرد هي الذراع العقاري لمجموعة إنترو للاستثمارات القابضة — تكتّل مصري تأسّس في السبعينيات ومملوك لعائلة عباس. تبني في رأس الحكمة والقاهرة الجديدة والمعادي و٦ أكتوبر، وتدير ذراعها الخاص للضيافة.','Ras Al Hekma · New Cairo · 6th of October','رأس الحكمة · القاهرة الجديدة · ٦ أكتوبر',2012,'#8a8378'),
  ('modon','Modon','مدن','Master-planned coastal destinations','وجهات ساحلية بمخططات متكاملة','A regional developer building large master-planned coastal destinations, active in Egypt on the Ras El Hekma North Coast.','مطوّر إقليمي يبني وجهات ساحلية كبرى بمخططات متكاملة، ونشط في مصر بمنطقة رأس الحكمة على الساحل الشمالي.','Ras El Hekma · North Coast','رأس الحكمة · الساحل الشمالي',2005,'#0f7b8c'),
  ('tmg','Talaat Moustafa Group','مجموعة طلعت مصطفى','Egypt’s largest integrated cities','أكبر المدن المتكاملة في مصر','One of Egypt’s largest developers, known for very large integrated cities and hospitality assets.','من أكبر المطوّرين في مصر، معروف بالمدن المتكاملة الضخمة وأصول الضيافة.','New Cairo · New Capital · North Coast','القاهرة الجديدة · العاصمة الإدارية · الساحل الشمالي',2007,'#1f6f5c'),
  ('emaarmisr','Emaar Misr','إعمار مصر','Premium integrated communities','مجتمعات متكاملة راقية','The Egyptian arm of a leading regional developer, known for premium integrated communities and coastal destinations.','الذراع المصري لمطوّر إقليمي رائد، معروف بالمجتمعات المتكاملة الراقية والوجهات الساحلية.','New Cairo · Sheikh Zayed · North Coast','القاهرة الجديدة · الشيخ زايد · الساحل الشمالي',2005,'#3a7a44'),
  ('hassanallam','Hassan Allam Properties','حسن علام العقارية','Engineering-led communities','مجتمعات بخبرة هندسية','The real-estate arm of a long-established Egyptian engineering and construction group.','الذراع العقاري لمجموعة هندسة وإنشاءات مصرية عريقة.','New Cairo · Mostakbal City · 6th of October','القاهرة الجديدة · مدينة المستقبل · ٦ أكتوبر',2010,'#b0473f'),
  ('madinetmasr','Madinet Masr','مدينة مصر','Established East Cairo communities','مجتمعات عريقة بشرق القاهرة','A long-established Egyptian developer building large communities in East Cairo.','مطوّر مصري عريق يبني مجتمعات كبرى بشرق القاهرة.','New Cairo · East Cairo','القاهرة الجديدة · شرق القاهرة',1959,'#c07a26'),
  ('cityedge','City Edge Developments','سيتي إيدج','New-city landmark destinations','وجهات مميّزة بالمدن الجديدة','A developer focused on landmark destinations across Egypt’s new cities, including North Coast towers.','مطوّر يركّز على وجهات مميّزة بالمدن الجديدة، منها أبراج الساحل الشمالي.','New Alamein · New Capital · North Coast','العلمين الجديدة · العاصمة الإدارية · الساحل الشمالي',2017,'#2b6ca8'),
  ('ilcazar','IL Cazar Developments','إل كازار','Design-forward launches','إطلاقات بتصميم متقدّم','A newer developer known for design-forward residential and coastal launches.','مطوّر حديث معروف بإطلاقات سكنية وساحلية بتصميم متقدّم.','New Cairo · North Coast','القاهرة الجديدة · الساحل الشمالي',2016,'#6d52a3'),
  ('lavista','La Vista Developments','لافيستا','Coastal & second-home specialist','متخصّص في المصايف والمنزل الثاني','A developer specialising in coastal and second-home communities along Egypt’s coasts.','مطوّر متخصّص في مجتمعات المصايف والمنزل الثاني على سواحل مصر.','North Coast · Ain Sokhna · New Cairo','الساحل الشمالي · العين السخنة · القاهرة الجديدة',1991,'#0d7b8c'),
  ('inertia','Inertia','إينرشيا','Lifestyle communities & coast','مجتمعات لايف ستايل ووجهات ساحلية','A developer known for lifestyle-led communities and North Coast destinations.','مطوّر معروف بمجتمعات لايف ستايل ووجهات على الساحل الشمالي.','North Coast · New Cairo · West Cairo','الساحل الشمالي · القاهرة الجديدة · غرب القاهرة',2007,'#3f7d3a'),
  ('alahlysabbour','Al Ahly Sabbour','الأهلي صبور','Broad residential portfolio','محفظة سكنية واسعة','A major developer with a broad residential portfolio across Cairo and the coast.','مطوّر كبير بمحفظة سكنية واسعة في القاهرة والساحل.','New Cairo · North Coast · Ain Sokhna','القاهرة الجديدة · الساحل الشمالي · العين السخنة',1994,'#8a6d33'),
  ('saudiegyptian','Saudi Egyptian Developers','السعودية المصرية للتعمير','Large-scale urban development','تطوير حضري واسع النطاق','A long-standing developer active in large-scale urban development in Egypt.','مطوّر عريق نشط في التطوير الحضري واسع النطاق في مصر.','New Cairo · New Capital','القاهرة الجديدة · العاصمة الإدارية',1975,'#26315f'),
  ('sumou','SumouBlvd.','سمو بوليفارد','Hospitality, culture and innovation districts','وجهات الضيافة والثقافة والابتكار','A leading Saudi developer of hospitality, entertainment and real-estate projects, focused on innovation, luxury and culture. It enters Egypt with Sumou Boulevard in Mostakbal City.','مطوّر سعودي رائد في مشروعات الضيافة والترفيه والعقارات، يركّز على الابتكار والفخامة والثقافة. يدخل السوق المصري بمشروع سمو بوليفارد في مدينة المستقبل.','Mostakbal City · East Cairo','مدينة المستقبل · شرق القاهرة',null,'#0077fe'),
  ('baghush','Marsa Baghush','مرسى باغوش','A place of good spirits','مكان الأرواح الطيبة','In the most sought-after area of the North Coast, where the sandy beaches and bluest of blue waters of Sidi Heneish are a welcomed reminder of what good living is all about, you can find a gem of the coast called Marsa Baghush. Just off the coastal road and linked to Cairo via the El Alamein and Dabaa roads, this part of the North Coast is now a stone’s throw from the capital.','في أكثر مناطق الساحل الشمالي رغبةً، حيث الشواطئ الرملية وأصفى مياه سيدي حنيش تذكّرك بمعنى الحياة الجيدة، تجد جوهرة الساحل التي تُسمّى مرسى باغوش. على مقربة من الطريق الساحلي ومتصل بالقاهرة عبر طريقي العلمين والضبعة، أصبح هذا الجزء من الساحل الشمالي على بُعد خطوة من العاصمة.','Sidi Heneish · North Coast','سيدي حنيش · الساحل الشمالي',null,'#636e63'),
  ('beitalbahr','Beit Al Bahr','بيت البحر','ELABD Resort, Sidi Heneish','منتجع العبد، سيدي حنيش','Beit Al Bahr is the result of a collaboration between leading entities in the Egyptian market, collectively forming BAM — a joint venture of El Abd, Gura and J Properties. Its mission is designing and building beachfront units that focus on privacy and exclusivity. A refined beachfront escape spread over 450 acres at El-Abd Resort, Sidi Heneish, with a private 3.5 km beach on the Mediterranean. The master plan loops around people and privacy, bringing homes closer to the seafront, the shimmering pools and the swimmable lagoons, with four boutique hotels, F&B tenants along the shore and native plantations throughout. Design draws on the four elements of life — air, water, earth and fire. Developer-direct primary units.','بيت البحر نتيجة تعاون بين كيانات رائدة في السوق المصري، تشكّل معاً «BAM» — مشروع مشترك بين العبد وجورا وجي بروبرتيز. ومهمتها تصميم وبناء وحدات على الشاطئ تركّز على الخصوصية والتميّز. ملاذ شاطئي راقٍ على ٤٥٠ فداناً في منتجع العبد بسيدي حنيش، بشاطئ خاص ٣٫٥ كم على البحر المتوسط. الماستر بلان يلتف حول الناس والخصوصية، فيقرّب المنازل من الشاطئ وحمامات السباحة والبحيرات القابلة للسباحة، مع أربعة فنادق بوتيك ومطاعم على الشاطئ ونباتات محلية في كل مكان. التصميم مستوحى من عناصر الحياة الأربعة — الهواء والماء والأرض والنار. وحدات أولية من المطوّر مباشرة.','Sidi Heneish · North Coast','سيدي حنيش · الساحل الشمالي',null,'#444991')
) as v(slug, name_en, name_ar, tagline_en, tagline_ar, description_en,
       description_ar, areas_line_en, areas_line_ar, founded_year, brand_colour)
on conflict (slug) do update set name_en = excluded.name_en, name_ar = excluded.name_ar,
  tagline_en = excluded.tagline_en, tagline_ar = excluded.tagline_ar,
  description_en = excluded.description_en, description_ar = excluded.description_ar,
  areas_line_en = excluded.areas_line_en, areas_line_ar = excluded.areas_line_ar,
  founded_year = excluded.founded_year, brand_colour = excluded.brand_colour;
